using RAWSelectionAssistant.Core.Services.Color;using RAWSelectionAssistant.Core.Services.Color.ControlledIcc;using RAWSelectionAssistant.Core.Services.Projects;
namespace RAWSelectionAssistant.Tests;
[TestClass]public sealed class LinearWideToolsTests
{
 static ColorAdjustmentStackNode Node(ColorStudioNodeType t,params (string,double)[] p)=>new(Guid.NewGuid(),t,"wide",NumericParameters:p.ToDictionary(x=>x.Item1,x=>x.Item2)){WideToolVersion=1,CompositeVersion=1};
 [TestMethod]public void VersionedWbAndToneRetainHdrRangeNeutralIdentityAndLegacyExposure()
 {
  var neutral=new ColorVector3(.18,.18,.18);foreach(var n in new[]{Node(ColorStudioNodeType.WhiteBalance),Node(ColorStudioNodeType.BasicTone)}){var r=new LinearWideToolsV1.Prepared(n).Apply(neutral);Assert.AreEqual(neutral.X,r.X,1e-12);Assert.AreEqual(neutral.Y,r.Y,1e-12);Assert.AreEqual(neutral.Z,r.Z,1e-12);}var hdr=new ColorVector3(-.2,.5,3);var tone=new LinearWideToolsV1.Prepared(Node(ColorStudioNodeType.BasicTone,("contrast",30),("highlights",-40),("shadows",20))).Apply(hdr);Assert.IsTrue(tone.X<0);Assert.IsTrue(tone.Z>1);Assert.AreEqual(hdr.X/hdr.Z,tone.X/tone.Z,1e-12);var wb=new LinearWideToolsV1.Prepared(Node(ColorStudioNodeType.WhiteBalance,("temperature",30),("tint",-15))).Apply(hdr);Assert.IsTrue(new[]{wb.X,wb.Y,wb.Z}.All(double.IsFinite));Assert.IsTrue(wb.Z>1);Assert.IsFalse(LinearWideToolsV1.Supported(Node(ColorStudioNodeType.Curve)));Assert.IsFalse(LinearWideToolsV1.Supported(Node(ColorStudioNodeType.BasicTone,("saturation",20))));
 }
 [TestMethod]public void OldV2ExposureOnlyKeepsExactHistoricalPerChannelResult()
 {
  using var cms=new LcmsRgbEngine();var d=new ProfessionalRawDefinition(ProcessingVersion:5,WhiteBalance:"Rendered",InputConfiguration:"RenderedSrgbFloatV1",DisplayTransform:"RenderedSrgbIdentityV1"){RenderedInputVersion=2,ColorState=new(cms.StandardProfile("DisplayP3"),cms.StandardProfile("LinearProPhotoD50V2"),cms.StandardProfile("ProPhotoRGB"),Version:2),LocalEdits=new(new([new(Guid.NewGuid(),ColorStudioNodeType.BasicTone,"old",NumericParameters:new Dictionary<string,double>{{"exposure",.37}}){CompositeVersion=1,Opacity=.61}],ProcessingVersion:2),2)};var data=new float[]{-.15f,.18f,1.4f,.3f,.9f,2.2f};var master=new ProfessionalRawMaster(new(2,1,data,"32f",DocumentWorkingRendererV2.Space),new("test","test","test",new string('a',64),d.DecodeKey,[],[],[],65535,OutputSpace:DocumentWorkingRendererV2.Space));using var actual=DocumentWorkingRendererV2.Region(master,d,0,0,2,1,CancellationToken.None);for(int i=0;i<data.Length;i++){double value=data[i];value+=value*(Math.Pow(2,.37)-1)*.61;Assert.AreEqual((float)value,actual.Rgb32.Span[i],0);}
 }
 [TestMethod]public void NativeLcmsBradfordMatchesIndependentPinnedReferenceCases()
 {
  var path=Environment.GetEnvironmentVariable("KITAO_WIDE_NUMERIC_REFERENCES");if(path is null){Assert.Inconclusive("Independent pinned numeric matrix required");return;}using var doc=System.Text.Json.JsonDocument.Parse(File.ReadAllText(path));using var cms=new LcmsRgbEngine();foreach(var row in doc.RootElement.GetProperty("whiteBalance").GetProperty("cases").EnumerateArray()){double t=row.GetProperty("temperature").GetDouble(),tint=row.GetProperty("tint").GetDouble(),x=.3457+t*.00025,y=.3585+tint*.0002;var v=row.GetProperty("input").EnumerateArray().Select(a=>a.GetDouble()).ToArray();var expected=row.GetProperty("independentBradford").EnumerateArray().Select(a=>a.GetDouble()).ToArray();var actual=cms.AdaptWhite(new(v[0],v[1],v[2]),new(x/y,1,(1-x-y)/y),new(.3457/.3585,1,(1-.3457-.3585)/.3585));Assert.AreEqual(expected[0],actual.X,1e-10);Assert.AreEqual(expected[1],actual.Y,1e-10);Assert.AreEqual(expected[2],actual.Z,1e-10);}
 }
 [TestMethod]public void LinearWorkingMaskZeroOpacityAndSerializationKeepDefinition()
 {
  using var cms=new LcmsRgbEngine();var d=new ProfessionalRawDefinition(ProcessingVersion:5,WhiteBalance:"Rendered",InputConfiguration:"RenderedSrgbFloatV1",DisplayTransform:"RenderedSrgbIdentityV1"){RenderedInputVersion=2,ColorState=new(cms.StandardProfile("DisplayP3"),cms.StandardProfile("LinearProPhotoD50V2"),cms.StandardProfile("ProPhotoRGB"),Version:2),LocalEdits=new(new([Node(ColorStudioNodeType.WhiteBalance,("temperature",20)),Node(ColorStudioNodeType.BasicTone,("highlights",-40),("shadows",30))],ProcessingVersion:2),2)};var data=Enumerable.Range(0,30*20*3).Select(i=>i%9==0?1.3f:(i%31)/20f).ToArray();var m=new ProfessionalRawMaster(new(30,20,data,"32f",DocumentWorkingRendererV2.Space),new("test","test","RGB",new string('a',64),d.DecodeKey,[],[],[],65535,OutputSpace:DocumentWorkingRendererV2.Space));using var result=DocumentWorkingRendererV2.Region(m,d,0,0,30,20,CancellationToken.None);Assert.IsTrue(result.Rgb32.Span.ToArray().All(float.IsFinite));var black=d with{LocalEdits=new(d.LocalEdits.Stack with{Nodes=d.LocalEdits.Stack.Nodes.Select(n=>n with{LocalMask=new([])}).ToArray()},2)};using var untouched=DocumentWorkingRendererV2.Region(m,black,0,0,30,20,CancellationToken.None);CollectionAssert.AreEqual(data,untouched.Rgb32.ToArray());var saved=System.Text.Json.JsonSerializer.Deserialize<ProfessionalRawDefinition>(System.Text.Json.JsonSerializer.Serialize(d))!;using var reopened=DocumentWorkingRendererV2.Region(m,saved,0,0,30,20,CancellationToken.None);CollectionAssert.AreEqual(result.Rgb32.ToArray(),reopened.Rgb32.ToArray());
 }
}
